import { calendarDate } from "@/lib/finance/calendar";
import { PhoneCollapse } from "@/components/phone-collapse";

type Named = { id: string; name: string };
export type FilterValues = Partial<Record<"q" | "from" | "to" | "account" | "category" | "merchant" | "status" | "kind" | "direction" | "tag" | "event" | "minAmount" | "maxAmount" | "sort" | "group", string>>;

const control = "min-h-10 w-full rounded-[10px] border border-input bg-card px-3 py-2 text-[13px]";

/**
 * Compact filter bar. Everything lives in the URL; amounts are typed as
 * decimals in the account (or display) currency and converted exactly to
 * minor units before they reach the URL.
 */
export function FilterBar({ values, accounts, categories, merchants, displayCurrency, timezone = "UTC" }: {
  values: FilterValues; accounts: (Named & { currency_code: string })[]; categories: Named[]; merchants: Named[]; displayCurrency: string; timezone?: string;
}) {
  const router = useRouter();
  const [account, setAccount] = useState(values.account ?? "");
  const [error, setError] = useState("");
  const currency = accounts.find(row => row.id === account)?.currency_code ?? displayCurrency;
  const decimal = (minor?: string) => minor === undefined ? "" : formatInputAmount(minor, currency);
  const [direction, setDirection] = useState(values.direction ?? "");
  const shown = shownBounds(values.direction, values.minAmount, values.maxAmount);
  const [more, setMore] = useState(Boolean(values.minAmount || values.maxAmount || values.status || values.kind || values.direction || values.tag || values.event));

  function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const form = new FormData(event.currentTarget);
    const params = new URLSearchParams();
    try {
      for (const [key, raw] of form) {
        const value = String(raw).trim();
        if (value && key !== "minAmount" && key !== "maxAmount") params.set(key, value);
      }
      const { minAmount, maxAmount } = amountBounds(direction, String(form.get("minAmount") ?? "").trim(), String(form.get("maxAmount") ?? "").trim(), currency);
      if (minAmount !== undefined) params.set("minAmount", minAmount.toString());
      if (maxAmount !== undefined) params.set("maxAmount", maxAmount.toString());
    } catch (cause) { setError(cause instanceof Error ? cause.message : "Check the amount"); return; }
    if (values.sort) params.set("sort", values.sort);
    setError("");
    router.push(`/money/transactions${params.size ? `?${params}` : ""}`);
  }

  function ask(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const text = String(new FormData(event.currentTarget).get("ask") ?? "").trim();
    if (!text) return;
    const { params } = compileFilterQuery(text, { today: calendarDate(new Date(), timezone), currency, accounts, categories, merchants });
    const query = new URLSearchParams(Object.entries(params).filter((entry): entry is [string, string] => Boolean(entry[1])));
    router.push(`/money/transactions${query.size ? `?${query}` : ""}`);
  }

  const filtering = Object.entries(values).some(([key, value]) => value && key !== "q" && key !== "sort" && key !== "group");
  return <div className="space-y-2">
  <form onSubmit={ask} role="search" aria-label="Describe transactions" className="flex flex-wrap gap-2 max-md:hidden">
    <input name="ask" maxLength={200} placeholder="Ask, e.g. coffee over 5 last month" aria-label="Describe what to find" className={`${control} flex-1`} />
    <button className="min-h-10 whitespace-nowrap rounded-[10px] border border-input px-3 text-[13px] hover:bg-muted">Find</button>
    <p className="basis-full text-xs text-muted-foreground">Find turns plain words into the filters shown below; words it doesn’t recognise search descriptions.</p>
  </form>
  <form onSubmit={submit} role="search" aria-label="Filter transactions" className="space-y-2">
      <input id="ledger-search" name="q" defaultValue={values.q} placeholder="Search descriptions  ( / )" aria-label="Search descriptions" maxLength={200} className={control} />
    <PhoneCollapse label="Filters" open={filtering}>
<div className="space-y-2">
    <div className="grid items-end gap-2 sm:grid-cols-2 lg:grid-cols-4">
      <label className="grid gap-1 text-xs text-muted-foreground">From<input name="from" type="date" defaultValue={values.from} aria-label="From date" className={`${control} text-foreground`} /></label>
      <label className="grid gap-1 text-xs text-muted-foreground">To<input name="to" type="date" defaultValue={values.to} aria-label="To date" className={`${control} text-foreground`} /></label>
      <select name="account" value={account} onChange={event => setAccount(event.target.value)} aria-label="Account" className={control}><option value="">All accounts</option>{accounts.map(row => <option key={row.id} value={row.id}>{row.name}</option>)}</select>
      <select name="category" defaultValue={values.category ?? ""} aria-label="Category" className={control}><option value="">All categories</option><option value="none">Uncategorized</option>{categories.map(row => <option key={row.id} value={row.id}>{row.name}</option>)}</select>
      <select name="merchant" defaultValue={values.merchant ?? ""} aria-label="Merchant" className={control}><option value="">All merchants</option><option value="none">Unknown</option>{merchants.map(row => <option key={row.id} value={row.id}>{row.name}</option>)}</select>
      {/* The links beside the results do this from md up. */}
      <select name="group" defaultValue={values.group ?? ""} aria-label="Group by" className={`${control} md:hidden`}><option value="">No grouping</option><option value="category">Group by category</option><option value="merchant">Group by merchant</option><option value="month">Group by month</option></select>
      <div className="flex gap-2 lg:col-span-2 lg:justify-end">
        <button type="button" aria-expanded={more} onClick={() => setMore(!more)} className="min-h-10 whitespace-nowrap rounded-[10px] border border-input px-3 text-[13px] hover:bg-muted">{more ? "Fewer" : "More"}</button>
        <button className="min-h-10 whitespace-nowrap rounded-[10px] bg-primary px-4 text-[13px] font-medium text-primary-foreground hover:opacity-90">Apply filters</button>
      </div>
    </div>
    <div hidden={!more} className="grid gap-2 sm:grid-cols-3 lg:grid-cols-7">
      <input key={`min-${currency}`} name="minAmount" defaultValue={decimal(shown.from)} placeholder={`From amount (${currency})`} aria-label={`Smallest amount in ${currency}`} inputMode="decimal" className={control} />
      <input key={`max-${currency}`} name="maxAmount" defaultValue={decimal(shown.to)} placeholder={`To amount (${currency})`} aria-label={`Largest amount in ${currency}`} inputMode="decimal" className={control} />
      <select name="direction" value={direction} onChange={event => setDirection(event.target.value)} aria-label="Direction" className={control}><option value="">Money in and out</option><option value="income">Money in</option><option value="outflow">Money out</option></select>
      <select name="status" defaultValue={values.status ?? ""} aria-label="Status" className={control}><option value="">Any status</option><option value="posted">Posted</option><option value="pending">Pending</option></select>
      <select name="kind" defaultValue={values.kind ?? ""} aria-label="Type" className={control}><option value="">Any type</option><option value="ordinary">Regular</option><option value="transfer">Transfer</option><option value="refund">Refund</option></select>
      <input name="tag" defaultValue={values.tag} placeholder="Tag" aria-label="Filter by tag" maxLength={40} className={control} />
      <input name="event" defaultValue={values.event} placeholder="Trip / event group" aria-label="Filter by spending group" maxLength={120} className={control} />
    </div>
</div>
    </PhoneCollapse>
    {more && <p className="text-xs text-muted-foreground">{direction ? `Type plain amounts: 10 to 50 finds ${direction === "income" ? "money in" : "purchases"} of 10 to 50.` : "Choose Money out or Money in to search by plain amounts. Without one, amounts are signed: -50 to -10 finds purchases of 10 to 50."}</p>}
    {error && <p role="alert" className="text-sm text-danger">{error}</p>}
  </form>
  </div>;
}
  const chips: [string, string][] = [
    ["q", filters.q && `“${filters.q}”`], ["from", filters.from && `From ${filters.from}`], ["to", filters.to && `To ${filters.to}`],
    ["account", filters.accountId && (accountNames[filters.accountId] ?? "Account")],
    ["category", filters.uncategorized ? "Uncategorized" : filters.categoryId && (categoryNames[filters.categoryId] ?? "Category")],
    ["merchant", filters.merchantUnknown ? "Unknown merchant" : filters.merchantId && (merchantNames[filters.merchantId] ?? "Merchant")],
    ["minAmount", filters.minAmountMinor !== undefined && (filters.direction === "outflow" ? `Up to ${formatMoney(filters.minAmountMinor.replace(/^-/, ""), amountCurrency, workspace.locale)}` : `At least ${formatMoney(filters.minAmountMinor, amountCurrency, workspace.locale)}`)],
    ["maxAmount", filters.maxAmountMinor !== undefined && (filters.direction === "outflow" ? `At least ${formatMoney(filters.maxAmountMinor.replace(/^-/, ""), amountCurrency, workspace.locale)}` : `At most ${formatMoney(filters.maxAmountMinor, amountCurrency, workspace.locale)}`)],
    ["direction", filters.direction && (filters.direction === "income" ? "Money in" : "Money out")],
    ["status", filters.status && statusLabel(filters.status)], ["kind", filters.kind && kindLabel(filters.kind)],
    ["tag", filters.tag && `Tag: ${filters.tag}`], ["event", filters.eventName && `Group: ${filters.eventName}`],
  ].filter((chip): chip is [string, string] => typeof chip[1] === "string" && chip[1] !== "");
  const filterValues = Object.fromEntries(shareable);
  const activeAccounts = (accounts ?? []).filter(account => !account.archived_at);

  return <main className="mx-auto w-full max-w-[1400px] space-y-5 px-4 py-4 text-foreground max-md:flex max-md:flex-col sm:px-8 md:py-6 lg:py-8">
    {header(filters.cursor ? null : count)}
    {viewId && !activeView ? <p role="alert" className="text-sm">Saved view not found. Showing normal filters.</p> : null}
    {/^\d+$/.test(params.applied ?? "") ? <p role="status" className="rounded-xl border border-border bg-card px-4 py-3 text-sm">Updated {params.applied} {params.applied === "1" ? "transaction" : "transactions"}. Showing that category. Undo the batch under <a className="underline" href="#editing-history">Editing history</a>, or <Link className="underline" href="/ai">return to the conversation</Link>.</p> : null}
    <div className="max-md:order-last"><PhoneCollapse label="Saved views" open={!!activeView}><SavedViewsPanel views={viewRows} activeViewId={activeView?.id ?? null} activeViewName={activeView?.name ?? null} saveDefaults={saveDefaults} /></PhoneCollapse></div>
    <div className="grid gap-6">
      <div className="min-w-0 space-y-4">
        <FilterBar key={shareable.toString()} values={filterValues} accounts={accounts ?? []} categories={categories ?? []} merchants={merchants ?? []} displayCurrency={workspace.display_currency} timezone={workspace.timezone} />
        <div className="flex flex-wrap items-center justify-between gap-3 text-sm">
          <ul aria-label="Active filters" className="flex flex-wrap items-center gap-1.5">
            {activeView ? <li className="rounded-full bg-brand/10 px-2.5 py-1 text-xs font-medium text-brand">View: {activeView.name}</li> : null}
            {chips.map(([key, label]) => <li key={key}><Link href={withParams(shareable, { [key]: null })} scroll={false} aria-label={`Remove filter ${label}`} className="inline-flex items-center gap-1 rounded-full border border-border bg-card px-2.5 py-1 text-xs hover:bg-muted">{label}<span aria-hidden>×</span></Link></li>)}
            {chips.length ? <li><Link href="/money/transactions" className="px-1 text-xs text-muted-foreground underline">Clear all</Link></li> : null}
          </ul>
          <div className="flex items-center gap-3 max-md:hidden max-lg:w-full max-lg:flex-wrap max-lg:justify-between">
            {count !== null ? <span className="font-mono text-xs text-muted-foreground max-lg:whitespace-nowrap">{filters.cursor ? `${count.toLocaleString(workspace.locale)} from here` : `${count.toLocaleString(workspace.locale)} ${count === 1 ? "transaction" : "transactions"}`}</span> : null}
            <nav aria-label="Group by" className="flex items-center gap-1 text-xs"><span className="text-muted-foreground">Group</span>
              {GROUPS.map(option => <Link key={option.value} scroll={false} aria-current={(filters.group ?? "") === option.value ? "true" : undefined}
                href={withParams(viewBase, { group: option.value || null, cursor: null })}
                className={`inline-flex min-h-11 items-center rounded-md px-2 py-1 max-lg:whitespace-nowrap lg:min-h-0 ${(filters.group ?? "") === option.value ? "bg-muted font-medium" : "text-muted-foreground hover:bg-muted"}`}>{option.label}</Link>)}
            </nav>
          </div>
        </div>
        {groups ? <p className="text-xs text-muted-foreground">
          {grouped?.data && count !== null && count > grouped.data.length ? `Subtotals cover the ${grouped.data.length.toLocaleString(workspace.locale)} most recent matches, not everything; narrow the dates for complete totals. ` : "Subtotals cover every match, including rows on other pages. "}
          {groups.by === "category" ? "Split transactions are grouped under their original category, so these can differ from spending reports, which use the allocations." : ""}</p> : null}
        {error ? <p role="alert">Could not load transactions: {error.message}</p> : <LedgerTable rows={rows} accountNames={accountNames} categories={categories ?? []} merchants={merchants ?? []}
          query={current.toString()} sort={filters.sort} sortHrefs={{ date: sortHref("date"), amount: sortHref("amount") }} groups={groups} openId={filters.transactionId ?? null}
          closeHref={`/money/transactions${current.size ? `?${current}` : ""}`} locale={workspace.locale} requestId={crypto.randomUUID()} />}
        <div className="flex flex-wrap items-center gap-4 text-sm">
          {filters.cursor ? <Link className="underline" href={withParams(viewBase, {})}>First page</Link> : null}
          {next ? <Link className="underline" href={withParams(viewBase, { cursor: next })}>Next page</Link> : null}
          <span className="text-xs text-muted-foreground">{filters.cursor ? `Showing ${pageRows.length} from here` : count !== null && count > pageRows.length ? `Showing 1–${pageRows.length} of ${count.toLocaleString(workspace.locale)}` : ""}</span>
          <p className="ml-auto hidden text-xs text-muted-foreground sm:block"><kbd>j</kbd>/<kbd>k</kbd> move · <kbd>Enter</kbd> open · <kbd>x</kbd> select · <kbd>/</kbd> search · <kbd>Esc</kbd> close</p>
        </div>
        <details id="add-transaction" open={params.add === "1"} className="scroll-mt-24 rounded-xl border border-border bg-card p-5">
          <summary className="cursor-pointer text-sm font-medium">Add a manual transaction</summary>
          {!activeAccounts.length ? <p className="mt-3 text-sm text-muted-foreground">A transaction needs an account. <Link className="underline" href="/money/accounts">Add or restore one in Accounts</Link>.</p> : <ManualTransactionForm accounts={activeAccounts} categories={categories ?? []} today={calendarDate(new Date(), workspace.timezone)} requestId={crypto.randomUUID()} />}
        </details>
        <Suspense fallback={<p className="text-sm text-muted-foreground">Loading batch history…</p>}>
          <div id="editing-history" className="scroll-mt-24" />
          <EditingHistory query={current.toString()} names={{ categories: categoryNames, merchants: merchantNames }} />
        </Suspense>
      </div>
    </div>
    {filters.transactionId ? <Suspense key={filters.transactionId} fallback={<aside aria-label="Loading transaction" className="fixed inset-y-0 right-0 z-50 w-full max-w-lg border-l border-border bg-card p-6 shadow-2xl"><p className="text-sm text-muted-foreground">Loading…</p></aside>}>
      <TransactionDrawer id={filters.transactionId} query={current.toString()} linkSearch={params.linkSearch?.trim().slice(0, 200) ?? ""} accountNames={accountNames} categories={categories ?? []} merchants={merchants ?? []} />
    </Suspense> : null}
  </main>;
}

